                    "sql": "create or replace table medmongers_db.maplemonk.medmongers_flipkart_seller_pla_pca_fact_items as ( with sku_level_data AS ( select *, date(cast(start_time as timestamp)) as report_date from medmongers_db.maplemonk.flipkart_medmongers_seller_portal_consolidated_fsn_pla ), campaign_daily_spend AS ( select \"Campaign ID\" AS CAMPAIGN_ID, DATE(CAST(START_TIME AS TIMESTAMP)) AS report_date, SUM(CAST(\"Ad Spend\" AS FLOAT)) AS total_campaign_spend from medmongers_db.maplemonk.Flipkart_MedMongers_seller_portal_pla group by 1, 2 ), sku_views_summary AS ( SELECT s.*, sum(s.views) over (partition by s.\"Campaign ID\", s.report_date) AS total_views_campaign_date FROM sku_level_data s ) SELECT cast(svs.ROI as float) as roi, \'FLIPKART\' Channel, \'FLIPKART SELLER PLA\' Account, cast(svs.VIEWS as int) as views, cast(svs.CLICKS as int) as clicks, cast(svs.\"Sku Id\" as string) as sku_id, sm.commonsku, case when lower(\"Sku Id\") like \'%inyou%\' then \'IN YOU\' else sm.brand end as brand, cast(svs.\"AdGroup ID\" as string) as adgroup_id, cast(svs.ACCOUNT_ID as string) as account_id, cast(svs.START_TIME as date) as date, cast(svs.\"Campaign ID\" as string) as campaign_id, cast(svs.\"AdGroup Name\" as string) as adgroup_name, cast(svs.\"Product Name\" as string) as product_name, cast(svs.\"Campaign Name\" as string) as campaign_name, cast(svs.\"Conversion Rate\" as float) as conversion_rate, cast(svs.\"Direct Units Sold\" as int) + cast(svs.\"Indirect Units Sold\" as int) as conversions, cast(svs.\"Total Revenue (Rs.)\" as float) as revenue, case when svs.total_views_campaign_date > 0 then (cast(svs.views as float) / svs.total_views_campaign_date) * cds.total_campaign_spend else 0 end as Spend from sku_views_summary svs left join campaign_daily_spend cds on svs.\"Campaign ID\" = cds.CAMPAIGN_ID AND svs.report_date = cds.report_date left join ( select channel_sku, upper(sku_code) as commonsku, upper(product_name) as product_name, upper(category) as product_category, upper(sub_category) as product_sub_category, landing_cost, mrp, brand, packaging_cost, tax_rate from medmongers_db.maplemonk.medmongers_final_sku_master where final_marketplace = \'FLIPKART\' qualify row_number() over (partition by lower(trim(channel_sku)) order by channelname) = 1 ) sm on lower(trim(sm.channel_sku)) = lower(trim(cast(svs.\"Sku Id\" as string))) ) UNION ALL select cast(\"Direct ROI\" as float) as Direct_ROI ,\'FLIPKART\' Channel ,\'FLIPKART SELLER PCA\' Account ,cast(views as int) Views ,cast(clicks as int) Clicks ,null as sku_id ,null as commonsku ,null as brand ,null as adgroup_id ,ACCOUNT_ID ,date(cast(cast(start_time as timestamp) as datetime)) date ,CAMPAIGN_ID ,null as adgroupname ,null as product_name ,CAMPAIGN_NAME ,null as conversion_rate ,(cast(\"DIRECT UNITS\" as int) + cast(\"INDIRECT UNITS\" as int)) Total_Converted_units ,(cast(\"DIRECT REVENUE\" as float) + cast(\"INDIRECT REVENUE\" as float)) Total_Revenue ,cast(campaign_spend as float) Spend from medmongers_db.maplemonk.Flipkart_MedMongers_seller_portal_pca ;",
